		if len(sha) > 7 {
			sha = sha[:7]
		}
		fmt.Fprintf(w, "%s  %s  %s  %s\n", a.Event, a.Author, sha, a.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
		if strings.TrimSpace(a.Body) != "" {
			fmt.Fprintf(w, "    %s\n", a.Body)
